<?php $editing=is_array($faculty);$pageTitle=$editing?'Edit faculty':'Add faculty';$values=array_merge($faculty??[],$old); ?>
<section class="page-heading"><div><p class="eyebrow">Faculty management</p><h1><?= $editing?'Edit faculty record':'Add faculty member' ?></h1><p>Active faculty can be considered for automatic invigilation allocation.</p></div><a class="secondary-button" href="<?= e(url('faculty')) ?>">Back to faculty</a></section>
<form class="record-form" method="post" action="<?= e($editing?url('faculty/'.$faculty['id']):url('faculty')) ?>"><?= csrf_field() ?><section class="panel form-section"><div class="form-section-heading"><p class="eyebrow">Identity</p><h2>Employment details</h2></div><div class="form-grid two"><label>Employee ID<input name="employee_id" value="<?= e($values['employee_id']??'') ?>" required><?php if(isset($errors['employee_id'])):?><b><?= e($errors['employee_id']) ?></b><?php endif;?></label><label>Name<input name="name" value="<?= e($values['name']??'') ?>" required><?php if(isset($errors['name'])):?><b><?= e($errors['name']) ?></b><?php endif;?></label><label>School<select name="school_id" required><option value="">Select school</option><?php foreach($schools as $school):?><option value="<?= (int)$school['id'] ?>" <?= (int)($values['school_id']??0)===(int)$school['id']?'selected':'' ?>><?= e($school['code'].' - '.$school['name']) ?></option><?php endforeach;?></select></label><label>Designation<input name="designation" value="<?= e($values['designation']??'') ?>" placeholder="Assistant Professor"></label><label>Email<input type="email" name="email" value="<?= e($values['email']??'') ?>"></label><label>Phone<input name="phone" value="<?= e($values['phone']??'') ?>"></label><label>Status<select name="status"><option value="active" <?= ($values['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= ($values['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></label></div></section><div class="form-actions"><a class="text-button" href="<?= e(url('faculty')) ?>">Cancel</a><button class="primary-button"><?= $editing?'Save changes':'Create faculty' ?></button></div></form>

